def load_state_dict(self, state_dict: Dict[str, Any]) -> None:
    if not state_dict:
        return

    # Check if the number of datasets in `state_dict["dataset"]` matches the number of datasets in the current object's `_datasets` attribute
    if len(state_dict["dataset"]) != len(self._datasets):
        raise RuntimeError("The number of datasets in `state_dict` does not match the number of datasets in the current object's `_datasets` attribute.")

    # Iterate over each dataset in the current object's `_datasets` using its index
    for i, dataset in enumerate(self._datasets):
